using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Options with the default reflection-based resolver ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>(): returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) TryGetTypeInfo<T>(): probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Person? p = JsonSerializer.Deserialize(json, info!);
    Console.WriteLine($"  Deserialized: Name={p!.Name}, Age={p.Age}");
}

// --- Options restricted to a source-gen context that only knows about Person ---
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = PersonOnlyContext.Default
};

// TryGetTypeInfo<T> returns false for an unresolved type — no exception
if (limited.TryGetTypeInfo<UnknownType>(out JsonTypeInfo<UnknownType>? missing))
{
    Console.WriteLine("Unexpected: resolved UnknownType");
}
else
{
    Console.WriteLine("TryGetTypeInfo<UnknownType> → false (metadata not available)");
}

// Confirm the same context *does* resolve Person
if (limited.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("TryGetTypeInfo<Person>      → true  (metadata available)");
}

// --- Types ---
public record Person(string Name, int Age);
public class UnknownType { public int X { get; set; } }

[JsonSerializable(typeof(Person))]
public partial class PersonOnlyContext : JsonSerializerContext;

